    counts = {}
    for row in grid:
        for value in row:
            if value:
                counts[value] = counts.get(value, 0) + 1
    frame = max(counts, key=counts.get)

    # The framed panel is the initial block of columns containing the frame color.
    panel_w = 0
    for c in range(w):
        if any(grid[r][c] == frame for r in range(h)):
            panel_w += 1
        else:
            break

    def shape(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    # Record the exact, orientation-preserving shape of each colored object.
    seen = set()
    objects = {}
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or color == frame or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and panel_w <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects[shape(cells)] = color

    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(panel_w))
    ]

    out = [row[:panel_w] for row in grid]
    for top, bottom in zip(separators, separators[1:]):
        holes = [
            (r, c)
            for r in range(top + 1, bottom)
            for c in range(panel_w)
            if grid[r][c] == 0
        ]
        if holes:
            color = objects.get(shape(holes))
            if color is not None:
                for r, c in holes:
                    out[r][c] = color

    return out
